INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (81, '戈雅', 'Francisco Goya', '1746—1828', '18—19世纪', '西班牙', '画家', ARRAY['画家', '西班牙', '浪漫主义'], '西班牙画家，从宫廷肖像到黑暗的战争图景，记录了一个动荡时代。他是浪漫主义的先声。', '宫廷画师友', '', 'assets/figures/goya.jpg', ARRAY['03-30', '04-01'], ARRAY['诞辰 · 1746年3月30日', '任宫廷画家 · 1786年'], ARRAY['birth', 'event'], '他给国王画像，你替他逗那些不肯安静的贵族。', ARRAY['宫廷画师友', '版画家'], ARRAY['他给国王画像，你替他逗那些不肯安静的贵族。', '那些讽刺版画，刻板你动的手，他只管落刀前的草图。']),
  (82, '透纳', 'J. M. W. Turner', '1775—1851', '18—19世纪', '英国', '画家', ARRAY['画家', '英国', '风景'], '英国风景画家，以光与大气的奔放表现著称。他的晚期作品预示了印象派的来临。', '皇家艺术院门房', '', 'assets/figures/turner.jpg', ARRAY['04-23', '02-01'], ARRAY['诞辰 · 1775年4月23日', '当选皇家艺术院院士 · 1802年'], ARRAY['birth', 'event'], '他进艺术院那年，门房是你，访客你比他认得全。', ARRAY['皇家艺术院门房', '海上旅伴'], ARRAY['他进艺术院那年，门房是你，访客你比他认得全。', '他追着风暴写生，船上有你掌舵，浪打来你先替他扶画架。']),
  (83, '蒙克', 'Edvard Munch', '1863—1944', '19—20世纪', '挪威', '画家', ARRAY['画家', '挪威', '表现主义'], '挪威表现主义画家，《呐喊》的作者。他以扭曲的形象直击现代人的焦虑与孤独，影响表现主义运动。', '奥斯陆画室友', '', 'assets/figures/munch.jpg', ARRAY['12-12', '01-01'], ARRAY['诞辰 · 1863年12月12日', '创作《呐喊》 · 1893年'], ARRAY['birth', 'event'], '你们合用一间画室，半夜他总在画，你替他留灯。', ARRAY['奥斯陆画室友', '木刻工'], ARRAY['你们合用一间画室，半夜他总在画，你替他留灯。', '《呐喊》那块木板，刻刀是你递的，他手抖时你扶过。']),
  (84, '荷马', 'Homer', '约前8世纪', '古希腊', '希腊', '诗人', ARRAY['文学家', '希腊', '史诗'], '古希腊史诗诗人，相传为《伊利亚特》与《奥德赛》的作者。这两部史诗奠定了西方文学的基石。', '吟游引路', '', 'assets/figures/homer.jpg', ARRAY['03-01', '01-01'], ARRAY['诞辰（传统） · 约前8世纪', '史诗传世 · 约前8世纪'], ARRAY['birth', 'event'], '他每到一城吟唱，提灯带路、清场的就是你。', ARRAY['吟游引路', '抄本保管'], ARRAY['他每到一城吟唱，提灯带路、清场的就是你。', '那两部史诗的抄本，收在你这口箱子里，谁借都要经你。']),
  (85, '但丁', 'Dante Alighieri', '1265—1321', '中世纪', '意大利', '诗人', ARRAY['文学家', '意大利', '史诗'], '意大利诗人，《神曲》的作者。他用托斯卡纳方言书写来世之旅，奠定了意大利文学语言的基础。', '流放同行', '', 'assets/figures/dante.jpg', ARRAY['05-21', '01-27'], ARRAY['诞辰 · 1265年5月21日', '开始流放 · 1302年1月27日'], ARRAY['birth', 'event'], '他被流放路上，与你同行一程，夜里分吃一块干面包。', ARRAY['流放同行', '方言校订'], ARRAY['他被流放路上，与你同行一程，夜里分吃一块干面包。', '他用方言写诗，发音你帮他校，错处他用指甲划掉。']),
  (86, '塞万提斯', 'Miguel de Cervantes', '1547—1616', '16—17世纪', '西班牙', '作家', ARRAY['文学家', '西班牙', '小说'], '西班牙作家，《堂吉诃德》的作者。这部小说以荒诞与深情并存的笔法，被誉为现代小说的开端。', '战俘信使', '', 'assets/figures/cervantes.jpg', ARRAY['09-29', '01-16'], ARRAY['诞辰 · 1547年9月29日', '《堂吉诃德》出版 · 1605年1月16日'], ARRAY['birth', 'event'], '勒班陀海战他负了伤，抬担架、替他包扎的有你。', ARRAY['战俘信使', '税吏旧识'], ARRAY['勒班陀海战他负了伤，抬担架、替他包扎的有你。', '他后来当税吏，账目你替他核过，漏收的你都补上。']),
  (87, '歌德', 'Johann W. von Goethe', '1749—1832', '18—19世纪', '德国', '诗人', ARRAY['文学家', '德国', '戏剧'], '德国诗人、剧作家与思想家，魏玛古典主义的代表。《浮士德》是其毕生思想的结晶。', '魏玛幕僚', '', 'assets/figures/goethe.jpg', ARRAY['08-28', '01-01'], ARRAY['诞辰 · 1749年8月28日', '《浮士德》上部出版 · 1808年'], ARRAY['birth', 'event'], '他在魏玛当大臣，文书你替他理，公文你先过目。', ARRAY['魏玛幕僚', '园艺师'], ARRAY['他在魏玛当大臣，文书你替他理，公文你先过目。', '他园子里的植物，你替他分了类，标本至今是你贴的签。']),
  (88, '马克·吐温', 'Mark Twain', '1835—1910', '19世纪', '美国', '作家', ARRAY['文学家', '美国', '小说'], '美国作家，以《哈克贝利·费恩历险记》闻名。他的幽默与方言写作刻画了密西西比河畔的美国。', '密西西比船工', '', 'assets/figures/twain.jpg', ARRAY['11-30', '12-10'], ARRAY['诞辰 · 1835年11月30日', '《哈克贝利·费恩》出版 · 1885年12月10日'], ARRAY['birth', 'event'], '密西西比河上，你是他学徒期的舵手，舵柄你扶得最稳。', ARRAY['密西西比船工', '报社校对'], ARRAY['密西西比河上，你是他学徒期的舵手，舵柄你扶得最稳。', '他写稿的报社，校样最后归你，标点你改得比他还狠。']),
  (89, '阿加莎·克里斯蒂', 'Agatha Christie', '1890—1976', '20世纪', '英国', '作家', ARRAY['文学家', '英国', '侦探'], '英国侦探小说女王，波洛与马普尔小姐的创造者。她是有史以来销量最高的作家之一，作品译成百余种语言。', '侦探小说编辑', '', 'assets/figures/christie.jpg', ARRAY['09-15', '10-01'], ARRAY['诞辰 · 1890年9月15日', '首部长篇出版 · 1920年'], ARRAY['birth', 'event'], '她的手稿，你是第一个读者，谜底你比编辑早知道三天。', ARRAY['侦探小说编辑', '考古随队'], ARRAY['她的手稿，你是第一个读者，谜底你比编辑早知道三天。', '她随丈夫考古，行李里总给你留一格，工具你替她扛。']),
  (90, '卡夫卡', 'Franz Kafka', '1883—1924', '19—20世纪', '奥地利', '小说家', ARRAY['文学家', '奥地利', '小说'], '奥地利德语小说家。《变形记》与《审判》以荒诞与压抑，定义了二十世纪的某种精神困境。', '工伤保险同事', '', 'assets/figures/kafka.jpg', ARRAY['07-03', '01-01'], ARRAY['诞辰 · 1883年7月3日', '《变形记》发表 · 1915年'], ARRAY['birth', 'event'], '他在劳工保险局上班，邻座是你，午休的咖啡你帮他带。', ARRAY['工伤保险同事', '夜稿抄写'], ARRAY['他在劳工保险局上班，邻座是你，午休的咖啡你帮他带。', '他夜里写的那些稿，清晨由你誊清，他常不认得自己的字。'])
